SELECT jsonb_build_object('capturado_em',transaction_timestamp(),'read_only',current_setting('transaction_read_only'),'counts',(SELECT to_jsonb(x) FROM(SELECT count(*) AS status0_concluinte,count(*) FILTER(WHERE r.homologado IS TRUE) AS approved,count(*) FILTER(WHERE r.homologado IS FALSE) AS homologado_false,count(*) FILTER(WHERE r.homologado IS NULL) AS homologado_null,count(*) FILTER(WHERE r.homologado IS TRUE AND r.sexo IS NULL) AS approved_null_sex,count(*) FILTER(WHERE r.homologado IS TRUE AND r.percurso IS NULL) AS approved_null_distance,count(*) FILTER(WHERE r.homologado IS TRUE AND char_length(r.sexo)<>1) AS approved_sex_length_not_one FROM public.tb_resultados r JOIN public.tb_evento_corridas e USING(id_evento) WHERE e.pais='BR' AND e.data_final>=DATE '2026-01-01' AND e.data_final<DATE '2026-10-01' AND r.status_final=0 AND r.concluinte IS TRUE)x))::text AS payload